(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.InverseTrigLesson,num=window.LinearLesson;
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
function piTex(n,d=1){const q=num.rational(n,d);if(q.n===0)return '0';const top=Math.abs(q.n)===1?'\\pi':Math.abs(q.n)+'\\pi';return(q.n<0?'-':'')+(q.d===1?top:`\\frac{${top}}{${q.d}}`);}
function decimal(x){return(Math.abs(x)<1e-10?0:x).toFixed(4).replace('.','{,}');}
function angle(x){const n=Math.round(x/Math.PI*12);return Math.abs(x-n*Math.PI/12)<1e-10?{tex:piTex(n,12),exact:true}:{tex:decimal(x),exact:false};}
function inputTex(n){const q=num.rational(n,10);return q.d===1?String(q.n):String.raw`\frac{${q.n}}{${q.d}}`;}
const names={sin:String.raw`\arcsin`,cos:String.raw`\arccos`,tan:String.raw`\arctan`},forward={sin:String.raw`\sin`,cos:String.raw`\cos`,tan:String.raw`\tan`},ranges={sin:String.raw`[-\pi/2,\pi/2]`,cos:String.raw`[0,\pi]`,tan:String.raw`(-\pi/2,\pi/2)`};
function draw(){const kind=$('#inverse-kind').value,n=Number($('#inverse-input').value),u=n/10,theta=core.principal(kind,u),arc=core.arc(kind);$('#input-output').value=String(u).replace('.',',');$('#inverse-input').setAttribute('aria-valuetext',String(u));$('#principal-arc').setAttribute('d',arc.map((p,i)=>`${i?'L':'M'}${p.x} ${p.y}`).join(' '));$('#principal-endpoints').innerHTML=[arc[0],arc[arc.length-1]].map(p=>`<circle cx="${p.x}" cy="${p.y}" r="4" fill="${kind==='tan'?'#fafaf5':'#466c8b'}" stroke="#466c8b" stroke-width="2"/>`).join('');math($('#inverse-range'),String.raw`\text{Rentang sudut utama: }${ranges[kind]}`);for(const id of ['inverse-ray','inverse-point'])$('#'+id).setAttribute('visibility',theta===null?'hidden':'visible');if(theta===null){$('#inverse-projection').setAttribute('d','');math($('#inverse-result'),names[kind]+String.raw`\left(${inputTex(n)}\right)\quad\text{tidak terdefinisi di bilangan real}`);$('#inverse-note').textContent='Masukan berada di luar interval negatif satu sampai satu. Tidak ada titik lingkaran yang sinus atau kosinusnya bernilai tersebut.';$('#inverse-plot').setAttribute('aria-label',`Busur utama ${kind==='sin'?'arcsin':'arccos'}. Masukan ${u} di luar domain; tidak ada sudut real yang dipilih.`);return;}const p=core.point(theta),a=angle(theta);$('#inverse-ray').setAttribute('x2',p.x);$('#inverse-ray').setAttribute('y2',p.y);$('#inverse-point').setAttribute('cx',p.x);$('#inverse-point').setAttribute('cy',p.y);$('#inverse-projection').setAttribute('d',`M180 ${p.y}H${p.x}V180`);math($('#inverse-result'),String.raw`\begin{aligned}\theta&=${names[kind]}\left(${inputTex(n)}\right)${a.exact?'=':String.raw`\approx`}${a.tex}\text{ rad}\\\theta&\approx${decimal(theta*180/Math.PI)}^\circ\\${forward[kind]}\theta&=${inputTex(n)}\end{aligned}`);$('#inverse-note').textContent=(kind==='sin'?'Sudut dipilih pada setengah lingkaran kanan, termasuk kedua ujungnya.':kind==='cos'?'Sudut dipilih pada setengah lingkaran atas, termasuk kedua ujungnya.':'Sudut dipilih pada setengah lingkaran kanan tanpa kedua ujungnya. Masukan adalah rasio koordinat tegak dibagi mendatar, bukan salah satu koordinat saja.')+' Nilai desimal ditampilkan sebagai pendekatan empat angka di belakang koma.';$('#inverse-plot').setAttribute('aria-label',`Sudut utama ${kind==='sin'?'arcsin':kind==='cos'?'arccos':'arctan'} untuk masukan ${u}, sekitar ${theta.toFixed(4)} radian atau ${(theta*180/Math.PI).toFixed(4)} derajat. Titik lingkaran sekitar (${Math.cos(theta).toFixed(4)}, ${Math.sin(theta).toFixed(4)}).`);}
for(const id of ['inverse-kind','inverse-input'])$('#'+id).addEventListener('input',draw);const cases={half:5,negative:-10,outside:15};document.querySelectorAll('[data-case]').forEach(e=>e.addEventListener('click',()=>{$('#inverse-input').value=cases[e.dataset.case];draw();}));$('#inverse-reset').addEventListener('click',()=>{$('#inverse-kind').value='sin';$('#inverse-input').value=5;draw();});draw();
function composition(){const deg=Number($('#composition-angle').value);$('#composition-output').value=deg+'°';const rows=['sin','cos','tan'].map(kind=>{const result=core.compose(kind,deg);return names[kind]+String.raw`\!\left(${forward[kind]}(${piTex(deg,180)})\right)&`+(result===null?String.raw`\text{ tidak terdefinisi}`:'='+angle(result).tex);});math($('#composition-result'),String.raw`\begin{aligned}x&=${piTex(deg,180)}\\`+rows.join(String.raw`\\`)+String.raw`\end{aligned}`);$('#composition-note').textContent=core.compose('tan',deg)===null?'Tangen sudut awal tidak terdefinisi karena kosinusnya nol. Karena itu, komposisi arctan dari tangen juga tidak terdefinisi. Arcsin dan arccos tetap memilih sudut pada rentang masing-masing.':'Bandingkan setiap hasil dengan sudut awal. Nilai trigonometri yang sama dapat berasal dari sudut yang berbeda; fungsi invers memilih sudut utama pada rentangnya.';}
$('#composition-angle').addEventListener('input',composition);document.querySelectorAll('[data-angle]').forEach(e=>e.addEventListener('click',()=>{$('#composition-angle').value=e.dataset.angle;composition();}));composition();
const questions=[{tex:String.raw`\arcsin(1/2)=c\pi`,prompt:'Berapa koefisien pi pada sudut utama ini?',n:1,d:6,hint:'Pilih sudut dengan sinus setengah yang berada antara negatif setengah pi dan setengah pi.',why:'Sudut utamanya pi per enam, sehingga koefisien pi adalah seperenam.'},{tex:String.raw`\arccos(-1/2)=c\pi`,prompt:'Berapa koefisien pi pada sudut utama ini?',n:2,d:3,hint:'Kosinus negatif dan rentang arccos nol sampai pi. Pilih sudut kuadran II.',why:'Sudut utamanya dua pi per tiga, sehingga koefisiennya dua per tiga.'},{tex:String.raw`\cos(\arcsin(3/5))`,prompt:'Berapa nilai fungsi ini?',n:4,d:5,hint:'Gunakan identitas Pythagoras dan tanda kosinus pada rentang arcsin.',why:'Kosinus sudut utama arcsin tidak negatif. Akar dari satu dikurangi sembilan per dua puluh lima adalah empat per lima.'}];const solved=new Set();function report(i,ok,text){const e=$('#feedback'+i);e.className='feedback '+(ok?'correct':'incorrect');e.textContent=text;if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><p>${q.prompt}</p><form data-question="${i}"><label for="answer${i}">Jawabanmu</label><div class="answer-line"><input id="answer${i}" type="text" required autocomplete="off" aria-describedby="feedback${i}"><button class="button" type="submit">Periksa jawaban</button></div></form><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('form[data-question]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.question),q=questions[i],a=num.parseAnswer($('#answer'+i).value),ok=num.equalAnswer(a,num.rational(q.n,q.d));report(i,ok,ok?'Tepat. '+q.why:!a?'Tulis bilangan atau pecahan yang diminta, misalnya 1/6 atau 4/5.':'Belum tepat. Periksa rentang sudut utama dan apakah soal meminta sudut atau nilai fungsi.');}));
const choices=[{tex:String.raw`\arcsin(\sin(5\pi/6))`,prompt:'Manakah hasil komposisi ini?',options:[{tex:String.raw`5\pi/6`,label:'Lima pi per enam'},{tex:String.raw`\pi/6`,label:'Pi per enam'},{tex:String.raw`-\pi/6`,label:'Negatif pi per enam'}],answer:1,why:'Sinus lima pi per enam adalah setengah. Arcsin setengah memilih pi per enam pada rentang sudut utamanya.'},{tex:String.raw`\arctan u`,prompt:'Manakah rentang keluaran untuk masukan real?',options:[{tex:String.raw`(-\pi/2,\pi/2)`,label:'Negatif setengah pi sampai setengah pi, kedua batas tidak masuk'},{tex:String.raw`[-\pi/2,\pi/2]`,label:'Negatif setengah pi sampai setengah pi, kedua batas masuk'},{tex:String.raw`[0,\pi]`,label:'Nol sampai pi, kedua batas masuk'}],answer:0,why:'Tangen tidak terdefinisi pada kedua batas tersebut. Arctan untuk masukan real berhingga tidak pernah mencapai kedua batas.'},{tex:String.raw`\sin^{-1}u`,prompt:'Jika notasi ini dipakai untuk invers sinus, apa artinya?',options:[{tex:String.raw`1/\sin u`,label:'Satu dibagi sinus u'},{tex:String.raw`(\sin u)^{-1}`,label:'Kebalikan dari nilai sinus u'},{tex:String.raw`\arcsin u`,label:'Arcsin u, sudut utama yang sinusnya u'}],answer:2,why:'Dalam konvensi fungsi invers, notasi tersebut berarti arcsin. Kebalikan nilai sinus adalah kosekan dan merupakan gagasan yang berbeda.'}];for(let j=0;j<choices.length;j++){const i=j+3,q=choices[j],box=document.createElement('div');box.className='question';box.innerHTML=`<h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><fieldset><legend>${q.prompt}</legend>${q.options.map((o,k)=>`<label class="choice"><input type="radio" name="choice${i}" value="${k}" ${o.label?'aria-label="'+o.label+'"':''}>${o.tex?'<span data-tex="'+o.tex+'"></span>':o.text}</label>`).join('')}</fieldset><button type="button" class="button" data-check="${i}">Periksa jawaban</button><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details>`;$('#questions').append(box);box.querySelector('button').addEventListener('click',()=>{const a=$(`[name="choice${i}"]:checked`),ok=!!a&&Number(a.value)===q.answer;report(i,ok,!a?'Pilih jawaban dahulu.':(ok?'Tepat. ':'Belum tepat. ')+q.why);});}
const storage={get(k){try{return localStorage.getItem('fondasi-inverse-trig-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-inverse-trig-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function complete(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>complete(storage.set('complete','yes')));if(storage.get('complete')==='yes')complete(true);
})();